```json::보안 암호
{
    "service-authorizer": {
        "account": {
            "database": {
                "username": "dbuserid",
                "password": "dbuserpassword"
            }
        },
        "payment": {
            "database": {
                "username": "paymentuserid",
                "password": "paymentuserpassword"
            }
        }
    },
    "content-server": {
