::

두 가지 방식 모두 구현하기 위해, 상위 클래스를 만들어 공통된 메서드를 정의한다.

::code-group
```cpp::(c++) 배열로 구현한 스택
#include <iostream>
#include "Stack.h"
using namespace std;

template <typename T>
class ArrayStack final : public Stack<T> {
private:
    T* arr;
    int top;
    int cap;
public:
    explicit ArrayStack(const int cap): top(-1), cap(cap) {
        arr = new T[cap];
    }

    ~ArrayStack() override {
        delete[] arr;
    }

    void push(const T& item) override {
        if (top == cap -1) {
            throw overflow_error("Stack is full");
        }
        arr[++top] = item;
    }

    T pop() override {
        if (is_empty()) {
            throw underflow_error("Stack is empty");
        }

        return arr[top--];
    }

    T peek() override {
        if (is_empty()) {
            throw underflow_error("Stack is empty");
        }

        return arr[top];
    }

    bool is_empty() override {
        return top == -1;
    }

    int size() override {
        return top + 1;
    }

    friend ostream& operator<<(ostream& os, const ArrayStack<T>& stack) {
        os << "Stack: [";
        for (int i = stack.top; i >= 0; i--) {
            os << stack.arr[i];
            if (0 < i) os << ",";
        }
        os << "]";
        return os;
    }
};
```
```java::(java) 배열로 구현한 스택
public class ArrayStack<T> implements Stack<T> {
    private T[] arr;
    private int top;
    private int cap;

    public ArrayStack(int cap) {
        this.top = -1;
        this.cap = cap;
        arr = (T[]) new Object[cap];
    }

    @Override
    public void push(T item) {
        if (top == cap - 1) {
            throw new StackOverflowError("Stack is full");
        }
        arr[++top] = item;
    }

    @Override
    public T pop() {
        if (isEmpty()) {
            throw new StackUnderflowError("Stack is empty");
        }
        return arr[top--];
    }

    @Override
    public T peek() {
        if (isEmpty()) {
            throw new StackUnderflowError("Stack is empty");
        }
        return arr[top];
    }

    @Override
    public boolean isEmpty() {
        return top == -1;
    }

    @Override
    public int size() {
        return top + 1;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("Stack [");
        for (int i = 0; i <= top; i++) {
            sb.append(arr[i]);
            if (i < top) sb.append(",");
        }
        sb.append("]");
        return sb.toString();
    }
}
```
