```cpp::(c++) 연결 리스트로 구현한 스택
#include "Stack.h"
#include <iostream>
using namespace std;


template <typename T>
class LinkedListStack : public Stack<T> {
private:

    //연결 리스트를 위한 Node 구조체
    struct Node {
        T data;
        Node* next;

        explicit Node(const T& value) : data(value), next(nullptr) {}
    };

    Node* top;
    int cap;

public:
    explicit LinkedListStack(int capacity) : cap(capacity), top(nullptr) {}
    ~LinkedListStack() override {
        while (top != nullptr) {
            Node* temp = top;
            top = top->next;
            delete temp;
        }
    }
    void push(const T &item) override {
        Node* newNode = new Node(item);
        newNode->next = top;
        top = newNode;
        cap++;
    }

    T pop() override {
        if (is_empty()) {
            throw underflow_error("Stack is empty");;
        }
        Node* temp = top;
        T popped = temp->data;
        top = top->next;
        delete temp;
        cap--;

        return popped;
    }

    T peek() override {
        if (is_empty()) {
            throw underflow_error("Stack is empty");;
        }
        return top->data;
    }

    bool is_empty() override {
        return top == nullptr;
    }

    int size() override {
        return top == nullptr ? 0 : cap;
    }

    friend ostream& operator<<(ostream& os, const LinkedListStack<T>& stack) {
        os << "Stack: [";
        Node* current = stack.top;
        while (current != nullptr) {
            os << current->data;
            if (current->next != nullptr) {
                os << ", ";
            }
            current = current->next;
        }
        os << "]";
        return os;
    }
};
```
```java::(java) 연결 리스트로 구현한 스택
public class LinkedListStack implements Stack {
    private Node top;
    private int cap;

    public LinkedListStack(int capacity) {
        this.cap = capacity;
        this.top = null;
    }

    @Override
    public void push(Object item) {
        Node newNode = new Node(item);
        newNode.next = top;
        top = newNode;
        cap++;
    }

    @Override
    public Object pop() {
        if (isEmpty()) {
            throw new StackUnderflowError("Stack is empty");
        }
        Node temp = top;
        Object popped = temp.data;
        top = top.next;
        temp.next = null;
        cap--;
        return popped;
    }

    @Override
    public Object peek() {
        if (isEmpty()) {
            throw new StackUnderflowError("Stack is empty");
        }
        return top.data;
    }

    @Override
    public boolean isEmpty() {
        return top == null;
    }

    @Override
    public int size() {
        return top == null ? 0 : cap;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder("Stack: [");
        Node current = top;
        while (current != null) {
            sb.append(current.data);
            if (current.next != null) {
                sb.append(", ");
            }
            current = current.next;
        }
        sb.append("]");

        return sb.toString();
    }

    public static class Node<T> {
        T data;
        Node next;

        public Node(T data) {
            this.data = data;
            this.next = null;
        }
    }
```
